theme.customCSS:
/* index-rezo-la-mer.css est PARTAGÉ : ses teintes océan (halo, bandeaux des searchHeader, dégradés) sont recolorées ici aux couleurs d'Open Atlas — rouge du logo sur l'encre bleu nuit. `:root:root` bat le `:root` de la feuille, `:root:root.dark` son `.dark`. */
:root:root {
  --ocean-deep: oklch(0.22 0.017 264);
  --ocean-mid: oklch(0.32 0.030 264);
  --ocean-light: oklch(0.45 0.120 18);
  --ocean-surface: oklch(0.60 0.209 18);
  --ocean-foam: oklch(0.93 0.035 18);
  --turquoise: var(--primary);
  --turquoise-light: color-mix(in oklab, var(--primary) 70%, white);
  --cyan-bright: var(--primary);
  --shadow-ocean: 0 10px 40px -10px oklch(0.22 0.017 264 / 0.45);
  --shadow-glow: 0 0 30px color-mix(in oklab, var(--primary) 35%, transparent);
  --text-shadow-glow: none; /* en clair, le halo rose floute le titre sombre */
  --gradient-section: linear-gradient(135deg, color-mix(in oklab, var(--primary) 8%, var(--background)), color-mix(in oklab, var(--accent) 70%, var(--background)));
}
:root:root.dark {
  --ocean-deep: oklch(0.16 0.015 264);
  --ocean-mid: oklch(0.24 0.025 264);
  --ocean-light: oklch(0.36 0.090 18);
  --shadow-ocean: 0 10px 40px -10px oklch(0 0 0 / 0.7);
  --shadow-glow: 0 0 40px color-mix(in oklab, var(--primary) 40%, transparent);
  --text-shadow-glow: 0 0 24px color-mix(in oklab, var(--primary) 35%, transparent);
  --gradient-section: linear-gradient(135deg, var(--ocean-deep), color-mix(in oklab, var(--primary) 16%, var(--ocean-mid)));
}
/* Héro d'accueil sans photo : halo rouge et bleu nuit, en écho au réseau de nœuds du logo. */
#accueil {
  background:
    radial-gradient(ellipse 60% 50% at 15% 20%, color-mix(in oklab, var(--primary) 12%, transparent), transparent 70%),
    radial-gradient(ellipse 55% 45% at 85% 85%, color-mix(in oklab, var(--ocean-mid) 12%, transparent), transparent 70%),
    var(--background);
}
